const { isHebrew, translateHebrew, buildFinalPrompt, RTL_OVERRIDE, RTL_POP } = require('../../../lib/common');

async function hebrew_translator(args) {
  const { prompt, reply_in_english = false, force_rtl = false, force_translate = false } = args;

  // Validate options
  if (force_rtl && reply_in_english) {
    return {
      success: false,
      error: 'Options --rtl and --english are incompatible'
    };
  }

  // Check if Hebrew
  const detectedHebrew = isHebrew(prompt) || force_translate;

  if (!detectedHebrew) {
    return {
      success: true,
      is_hebrew: false,
      original: prompt,
      translated: null,
      final_prompt: prompt,
      message: 'Text is not Hebrew, returning as-is'
    };
  }

  // Translate
  let translated;
  let translationError;
  try {
    const result = await translateHebrew(prompt);
    translated = result.translated;
  } catch (error) {
    console.error('Translation failed:', error.message);
    translationError = error.message;
    translated = prompt;
  }

  const { finalPrompt, rtlFormatted } = buildFinalPrompt(translated, {
    replyInEnglish: reply_in_english,
    forceRTL: force_rtl
  });

  const response = {
    success: true,
    is_hebrew: true,
    original: prompt,
    translated,
    final_prompt: finalPrompt,
    response_language: reply_in_english ? 'English' : 'Hebrew',
    token_savings_estimate: 'Up to 40% on input tokens'
  };

  if (translationError) {
    response.translation_warning = `Translation failed: ${translationError}. Using original text.`;
  }

  return response;
}

module.exports = { hebrew_translator };
